  1→/**
  2→ * Lead Reactivation Observability Dashboard
  3→ *
  4→ * Provides n8n-style execution trace visualization.
  5→ * Fetches traces from Supabase and serves a React Flow dashboard.
  6→ */
  7→
  8→import { Hono } from 'hono';
  9→import { cors } from 'hono/cors';
 10→import { serveStatic } from 'hono/bun';
 11→import { createClient } from '@supabase/supabase-js';
 12→
 13→// Environment configuration
 14→const SUPABASE_URL = process.env.SUPABASE_URL!;
 15→const SUPABASE_SERVICE_KEY = process.env.SUPABASE_SERVICE_KEY!;
 16→const PORT = parseInt(process.env.PORT || '3456');
 17→
 18→if (!SUPABASE_URL || !SUPABASE_SERVICE_KEY) {
 19→  console.error('Missing SUPABASE_URL or SUPABASE_SERVICE_KEY environment variables');
 20→  console.log('Set them via:');
 21→  console.log('  export SUPABASE_URL="your-supabase-url"');
 22→  console.log('  export SUPABASE_SERVICE_KEY="your-service-key"');
 23→  process.exit(1);
 24→}
 25→
 26→const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_KEY);
 27→
 28→const app = new Hono();
 29→
 30→// Enable CORS for development
 31→app.use('*', cors());
 32→
 33→// Serve static files from public directory
 34→app.use('/static/*', serveStatic({ root: './' }));
 35→
 36→// API: Get recent executions list
 37→app.get('/api/traces', async (c) => {
 38→  const limit = parseInt(c.req.query('limit') || '50');
 39→
 40→  const { data, error } = await supabase
 41→    .from('recent_executions')
 42→    .select('*')
 43→    .limit(limit);
 44→
 45→  if (error) {
 46→    console.error('Error fetching traces:', error);
 47→    return c.json({ error: error.message }, 500);
 48→  }
 49→
 50→  return c.json(data || []);
 51→});
 52→
 53→// API: Get single trace with all spans
 54→app.get('/api/traces/:traceId', async (c) => {
 55→  const traceId = c.req.param('traceId');
 56→
 57→  const { data, error } = await supabase.rpc('get_trace', {
 58→    p_trace_id: traceId,
 59→  });
 60→
 61→  if (error) {
 62→    console.error('Error fetching trace:', error);
 63→    return c.json({ error: error.message }, 500);
 64→  }
 65→
 66→  // Transform spans into a hierarchical structure for visualization
 67→  const spans = data || [];
 68→  const nodes = spans.map((span: any, index: number) => ({
 69→    id: span.span_id,
 70→    parentId: span.parent_span_id,
 71→    data: {
 72→      label: span.name,
 73→      nodeType: span.node_type,
 74→      status: span.status,
 75→      duration: span.duration_ms,
 76→      startedAt: span.started_at,
 77→      endedAt: span.ended_at,
 78→      error: span.error_message,
 79→      input: span.input_data,
 80→      output: span.output_data,
 81→      metadata: span.metadata,
 82→      leadId: span.lead_id,
 83→      centreId: span.centre_id,
 84→    },
 85→    // Position will be calculated by the frontend
 86→    position: { x: 0, y: index * 100 },
 87→  }));
 88→
 89→  // Build edges from parent relationships
 90→  const edges = spans
 91→    .filter((span: any) => span.parent_span_id)
 92→    .map((span: any) => ({
 93→      id: `${span.parent_span_id}-${span.span_id}`,
 94→      source: span.parent_span_id,
 95→      target: span.span_id,
 96→      animated: span.status === 'running',
 97→    }));
 98→
 99→  return c.json({
100→    traceId,

100→    traceId,
101→    nodes,
102→    edges,
103→    rawSpans: spans,
104→  });
105→});
106→
107→// API: Get lead details (for drill-down)
108→app.get('/api/leads/:leadId', async (c) => {
109→  const leadId = c.req.param('leadId');
110→
111→  const { data, error } = await supabase
112→    .from('leads')
113→    .select('*, call_attempts(*)')
114→    .eq('id', leadId)
115→    .single();
116→
117→  if (error) {
118→    return c.json({ error: error.message }, 500);
119→  }
120→
121→  return c.json(data);
122→});
123→
124→// Serve dashboard HTML
125→app.get('/', async (c) => {
126→  return c.html(dashboardHtml);
127→});
128→
129→// Health check
130→app.get('/health', (c) => c.json({ status: 'ok', timestamp: new Date().toISOString() }));
131→
132→console.log(`
