147→const dashboardHtml = `<!DOCTYPE html>
148→<html lang="en">
149→<head>
150→  <meta charset="UTF-8">
151→  <meta name="viewport" content="width=device-width, initial-scale=1.0">
152→  <title>Lead Reactivation - Execution Traces</title>
153→  <script src="https://unpkg.com/react@18/umd/react.production.min.js"></script>
154→  <script src="https://unpkg.com/react-dom@18/umd/react-dom.production.min.js"></script>
155→  <script src="https://unpkg.com/@xyflow/react@12/dist/umd/index.js"></script>
156→  <link href="https://unpkg.com/@xyflow/react@12/dist/style.css" rel="stylesheet" />
157→  <script src="https://cdn.tailwindcss.com"></script>
158→  <style>
159→    .react-flow__node-custom {
160→      padding: 10px 15px;
161→      border-radius: 8px;
162→      border: 2px solid #374151;
163→      font-size: 12px;
164→      min-width: 150px;
165→    }
166→    .react-flow__node-custom.success { background: #065f46; border-color: #10b981; }
167→    .react-flow__node-custom.error { background: #7f1d1d; border-color: #ef4444; }
168→    .react-flow__node-custom.running { background: #1e3a5f; border-color: #3b82f6; animation: pulse 2s infinite; }
169→    .react-flow__node-custom.skipped { background: #374151; border-color: #6b7280; }
170→
171→    @keyframes pulse {
172→      0%, 100% { opacity: 1; }
173→      50% { opacity: 0.7; }
174→    }
175→
176→    .node-icon {
177→      display: inline-block;
178→      width: 16px;
179→      height: 16px;
180→      margin-right: 6px;
181→      vertical-align: middle;
182→    }
183→  </style>
184→</head>
185→<body class="bg-gray-900 text-white">
186→  <div id="root" class="h-screen"></div>
187→
188→  <script>
189→    const { useState, useEffect, useCallback, useMemo } = React;
190→    const { ReactFlow, Background, Controls, MiniMap, useNodesState, useEdgesState, Handle, Position } = window.XYFlow;
191→
192→    // Node type icons
193→    const nodeIcons = {
194→      trigger: '⚡',
195→      database: '🗄️',
196→      api: '🌐',
197→      webhook: '📥',
198→      logic: '⚙️',
199→      output: '📤',
200→    };
201→
202→    // Status colors for the list
203→    const statusColors = {
204→      success: 'bg-green-600',
205→      error: 'bg-red-600',
206→      running: 'bg-blue-600',
207→      skipped: 'bg-gray-600',
208→    };
209→
210→    // Custom node component
211→    function CustomNode({ data }) {
212→      return React.createElement('div', { className: 'text-white' },
213→        React.createElement(Handle, { type: 'target', position: Position.Top, className: 'w-2 h-2' }),
214→        React.createElement('div', { className: 'flex items-center gap-2' },
215→          React.createElement('span', { className: 'text-lg' }, nodeIcons[data.nodeType] || '📦'),
216→          React.createElement('div', null,
217→            React.createElement('div', { className: 'font-semibold' }, data.label),
218→            data.duration != null && React.createElement('div', { className: 'text-xs text-gray-300' }, data.duration + 'ms')
219→          )
220→        ),
221→        data.error && React.createElement('div', { className: 'text-xs text-red-300 mt-1 truncate max-w-[180px]' }, data.error),
222→        React.createElement(Handle, { type: 'source', position: Position.Bottom, className: 'w-2 h-2' })
223→      );
224→    }
225→
226→    const nodeTypes = { custom: CustomNode };
227→
228→    // Main App component
229→    function App() {
230→      const [traces, setTraces] = useState([]);
231→      const [selectedTrace, setSelectedTrace] = useState(null);
232→      const [traceData, setTraceData] = useState(null);
233→      const [selectedNode, setSelectedNode] = useState(null);
234→      const [loading, setLoading] = useState(true);
235→
236→      const [nodes, setNodes, onNodesChange] = useNodesState([]);
237→      const [edges, setEdges, onEdgesChange] = useEdgesState([]);
238→
239→      // Fetch traces list
240→      useEffect(() => {
241→        fetch('/api/traces')
242→          .then(r => r.json())
243→          .then(data => {
244→            setTraces(data);
245→            setLoading(false);
246→            if (data.length > 0 && !selectedTrace) {
247→              setSelectedTrace(data[0].trace_id);
248→            }
249→          })
250→          .catch(err => {
251→            console.error('Failed to fetch traces:', err);
252→            setLoading(false);
253→          });
254→      }, []);
255→
256→      // Fetch selected trace details
257→      useEffect(() => {
258→        if (!selectedTrace) return;
259→
260→        fetch('/api/traces/' + selectedTrace)
261→          .then(r => r.json())
262→          .then(data => {
263→            setTraceData(data);
264→
265→            // Layout nodes in a tree structure
266→            const layoutedNodes = layoutNodes(data.nodes, data.edges);
267→            setNodes(layoutedNodes);
268→            setEdges(data.edges.map(e => ({ ...e, type: 'smoothstep', style: { stroke: '#6b7280' } })));
269→          })
270→          .catch(err => console.error('Failed to fetch trace:', err));
271→      }, [selectedTrace]);
272→
273→      // Simple tree layout algorithm
274→      function layoutNodes(nodes, edges) {
275→        if (!nodes.length) return [];
276→
277→        // Build parent-child map
278→        const childrenMap = new Map();
279→        const parentMap = new Map();
280→
281→        edges.forEach(e => {
282→          if (!childrenMap.has(e.source)) childrenMap.set(e.source, []);
283→          childrenMap.get(e.source).push(e.target);
284→          parentMap.set(e.target, e.source);
285→        });
286→
287→        // Find root nodes (no parent)
288→        const roots = nodes.filter(n => !parentMap.has(n.id));
289→
290→        // BFS to assign positions
291→        const positions = new Map();
292→        const queue = roots.map((n, i) => ({ id: n.id, depth: 0, index: i }));
293→        const depthCounts = new Map();
294→
295→        while (queue.length > 0) {
296→          const { id, depth, index } = queue.shift();
297→
298→          if (!depthCounts.has(depth)) depthCounts.set(depth, 0);
299→          const xIndex = depthCounts.get(depth);
300→          depthCounts.set(depth, xIndex + 1);
301→
302→          positions.set(id, { x: xIndex * 220, y: depth * 120 });
303→
304→          const children = childrenMap.get(id) || [];
305→          children.forEach((childId, i) => {
306→            queue.push({ id: childId, depth: depth + 1, index: i });
307→          });
308→        }
309→
310→        // Apply positions and styling
311→        return nodes.map(n => ({
312→          ...n,
313→          position: positions.get(n.id) || { x: 0, y: 0 },
314→          type: 'custom',
315→          className: 'react-flow__node-custom ' + (n.data.status || 'running'),
316→        }));
317→      }
318→
319→      const onNodeClick = useCallback((event, node) => {
320→        setSelectedNode(node);
321→      }, []);
322→
323→      // Format timestamp for display
324→      function formatTime(iso) {
325→        if (!iso) return '-';
326→        const d = new Date(iso);
327→        return d.toLocaleTimeString();
328→      }
329→
330→      return React.createElement('div', { className: 'flex h-screen' },
331→        // Left sidebar - trace list
332→        React.createElement('div', { className: 'w-80 bg-gray-800 border-r border-gray-700 overflow-auto' },
333→          React.createElement('div', { className: 'p-4 border-b border-gray-700' },
334→            React.createElement('h1', { className: 'text-xl font-bold' }, '⚡ Execution Traces'),
335→            React.createElement('p', { className: 'text-sm text-gray-400 mt-1' }, 'Lead Reactivation System')
336→          ),
337→          React.createElement('div', { className: 'p-2' },
338→            loading
339→              ? React.createElement('div', { className: 'text-center py-8 text-gray-400' }, 'Loading...')
340→              : traces.length === 0
341→                ? React.createElement('div', { className: 'text-center py-8 text-gray-400' }, 'No traces yet')
342→                : traces.map(trace =>
343→                    React.createElement('div', {
344→                      key: trace.trace_id,
345→                      className: 'p-3 mb-2 rounded-lg cursor-pointer transition-colors ' +
346→                        (selectedTrace === trace.trace_id ? 'bg-blue-900 border border-blue-600' : 'bg-gray-700 hover:bg-gray-600'),
347→                      onClick: () => setSelectedTrace(trace.trace_id)
348→                    },
349→                      React.createElement('div', { className: 'flex items-center justify-between' },
350→                        React.createElement('span', { className: 'font-medium' }, trace.trigger_type || 'scheduler_run'),
351→                        React.createElement('span', {
352→                          className: 'px-2 py-0.5 rounded text-xs ' + (statusColors[trace.status] || 'bg-gray-600')
353→                        }, trace.status)
354→                      ),
355→                      React.createElement('div', { className: 'text-xs text-gray-400 mt-1' },
356→                        formatTime(trace.started_at),
357→                        trace.duration_ms && ' • ' + trace.duration_ms + 'ms'
358→                      ),
359→                      React.createElement('div', { className: 'text-xs text-gray-400' },
