/**
 * Lead Reactivation Observability Dashboard
 *
 * Provides n8n-style execution trace visualization.
 * Fetches traces from Supabase and serves a React Flow dashboard.
 */

import { Hono } from 'hono';
import { cors } from 'hono/cors';
import { serveStatic } from 'hono/bun';
import { createClient } from '@supabase/supabase-js';

// Environment configuration
const SUPABASE_URL = process.env.SUPABASE_URL!;
const SUPABASE_SERVICE_KEY = process.env.SUPABASE_SERVICE_KEY!;
const PORT = parseInt(process.env.PORT || '3456');

if (!SUPABASE_URL || !SUPABASE_SERVICE_KEY) {
  console.error('Missing SUPABASE_URL or SUPABASE_SERVICE_KEY environment variables');
  console.log('Set them via:');
  console.log('  export SUPABASE_URL="your-supabase-url"');
  console.log('  export SUPABASE_SERVICE_KEY="your-service-key"');
  process.exit(1);
}

const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_KEY);

const app = new Hono();

// Enable CORS for development
app.use('*', cors());

// Serve static files from public directory
app.use('/static/*', serveStatic({ root: './' }));

// API: Get recent executions list
app.get('/api/traces', async (c) => {
  const limit = parseInt(c.req.query('limit') || '50');

  const { data, error } = await supabase
    .from('recent_executions')
    .select('*')
    .limit(limit);

  if (error) {
    console.error('Error fetching traces:', error);
    return c.json({ error: error.message }, 500);
  }

  return c.json(data || []);
});

// API: Get single trace with all spans
app.get('/api/traces/:traceId', async (c) => {
  const traceId = c.req.param('traceId');

  const { data, error } = await supabase.rpc('get_trace', {
    p_trace_id: traceId,
  });

  if (error) {
    console.error('Error fetching trace:', error);
    return c.json({ error: error.message }, 500);
  }

  // Transform spans into a hierarchical structure for visualization
  const spans = data || [];
  const nodes = spans.map((span: any, index: number) => ({
    id: span.span_id,
    parentId: span.parent_span_id,
    data: {
      label: span.name,
      nodeType: span.node_type,
      status: span.status,
      duration: span.duration_ms,
      startedAt: span.started_at,
      endedAt: span.ended_at,
      error: span.error_message,
      input: span.input_data,
      output: span.output_data,
      metadata: span.metadata,
      leadId: span.lead_id,
      centreId: span.centre_id,
    },
    // Position will be calculated by the frontend
    position: { x: 0, y: index * 100 },
  }));

  // Build edges from parent relationships
  const edges = spans
    .filter((span: any) => span.parent_span_id)
    .map((span: any) => ({
      id: `${span.parent_span_id}-${span.span_id}`,
      source: span.parent_span_id,
      target: span.span_id,
      animated: span.status === 'running',
    }));

  return c.json({
    traceId,
    nodes,
    edges,
    rawSpans: spans,
  });
});

// API: Get lead details (for drill-down)
app.get('/api/leads/:leadId', async (c) => {
  const leadId = c.req.param('leadId');

  const { data, error } = await supabase
    .from('leads')
    .select('*, call_attempts(*)')
    .eq('id', leadId)
    .single();

  if (error) {
    return c.json({ error: error.message }, 500);
  }

  return c.json(data);
});

// Serve dashboard HTML
app.get('/', async (c) => {
  return c.html(dashboardHtml);
});

// Health check
app.get('/health', (c) => c.json({ status: 'ok', timestamp: new Date().toISOString() }));

console.log(`
╔═══════════════════════════════════════════════════════════╗
║     Lead Reactivation Observability Dashboard             ║
╠═══════════════════════════════════════════════════════════╣
║  Dashboard:  http://localhost:${PORT}                       ║
║  API:        http://localhost:${PORT}/api/traces              ║
╚═══════════════════════════════════════════════════════════╝
`);

export default {
  port: PORT,
  fetch: app.fetch,
};

// Embedded dashboard HTML with React Flow
const dashboardHtml = `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Lead Reactivation - Execution Traces</title>
  <script src="https://unpkg.com/react@18/umd/react.production.min.js"></script>
  <script src="https://unpkg.com/react-dom@18/umd/react-dom.production.min.js"></script>
  <script src="https://unpkg.com/@xyflow/react@12/dist/umd/index.js"></script>
  <link href="https://unpkg.com/@xyflow/react@12/dist/style.css" rel="stylesheet" />
  <script src="https://cdn.tailwindcss.com"></script>
  <style>
    .react-flow__node-custom {
      padding: 10px 15px;
      border-radius: 8px;
      border: 2px solid #374151;
      font-size: 12px;
      min-width: 150px;
    }
    .react-flow__node-custom.success { background: #065f46; border-color: #10b981; }
    .react-flow__node-custom.error { background: #7f1d1d; border-color: #ef4444; }
    .react-flow__node-custom.running { background: #1e3a5f; border-color: #3b82f6; animation: pulse 2s infinite; }
    .react-flow__node-custom.skipped { background: #374151; border-color: #6b7280; }

    @keyframes pulse {
      0%, 100% { opacity: 1; }
      50% { opacity: 0.7; }
    }

    .node-icon {
      display: inline-block;
      width: 16px;
      height: 16px;
      margin-right: 6px;
      vertical-align: middle;
    }
  </style>
</head>
<body class="bg-gray-900 text-white">
  <div id="root" class="h-screen"></div>

  <script>
    const { useState, useEffect, useCallback, useMemo } = React;
    const { ReactFlow, Background, Controls, MiniMap, useNodesState, useEdgesState, Handle, Position } = window.XYFlow;

    // Node type icons
    const nodeIcons = {
      trigger: '⚡',
      database: '🗄️',
      api: '🌐',
      webhook: '📥',
      logic: '⚙️',
      output: '📤',
    };

    // Status colors for the list
    const statusColors = {
      success: 'bg-green-600',
      error: 'bg-red-600',
      running: 'bg-blue-600',
      skipped: 'bg-gray-600',
    };

    // Custom node component
    function CustomNode({ data }) {
      return React.createElement('div', { className: 'text-white' },
        React.createElement(Handle, { type: 'target', position: Position.Top, className: 'w-2 h-2' }),
        React.createElement('div', { className: 'flex items-center gap-2' },
          React.createElement('span', { className: 'text-lg' }, nodeIcons[data.nodeType] || '📦'),
          React.createElement('div', null,
            React.createElement('div', { className: 'font-semibold' }, data.label),
            data.duration != null && React.createElement('div', { className: 'text-xs text-gray-300' }, data.duration + 'ms')
          )
        ),
        data.error && React.createElement('div', { className: 'text-xs text-red-300 mt-1 truncate max-w-[180px]' }, data.error),
        React.createElement(Handle, { type: 'source', position: Position.Bottom, className: 'w-2 h-2' })
      );
    }

    const nodeTypes = { custom: CustomNode };

    // Main App component
    function App() {
      const [traces, setTraces] = useState([]);
      const [selectedTrace, setSelectedTrace] = useState(null);
      const [traceData, setTraceData] = useState(null);
      const [selectedNode, setSelectedNode] = useState(null);
      const [loading, setLoading] = useState(true);

      const [nodes, setNodes, onNodesChange] = useNodesState([]);
      const [edges, setEdges, onEdgesChange] = useEdgesState([]);

      // Fetch traces list
      useEffect(() => {
        fetch('/api/traces')
          .then(r => r.json())
          .then(data => {
            setTraces(data);
            setLoading(false);
            if (data.length > 0 && !selectedTrace) {
              setSelectedTrace(data[0].trace_id);
            }
          })
          .catch(err => {
            console.error('Failed to fetch traces:', err);
            setLoading(false);
          });
      }, []);

      // Fetch selected trace details
      useEffect(() => {
        if (!selectedTrace) return;

        fetch('/api/traces/' + selectedTrace)
          .then(r => r.json())
          .then(data => {
            setTraceData(data);

            // Layout nodes in a tree structure
            const layoutedNodes = layoutNodes(data.nodes, data.edges);
            setNodes(layoutedNodes);
            setEdges(data.edges.map(e => ({ ...e, type: 'smoothstep', style: { stroke: '#6b7280' } })));
          })
          .catch(err => console.error('Failed to fetch trace:', err));
      }, [selectedTrace]);

      // Simple tree layout algorithm
      function layoutNodes(nodes, edges) {
        if (!nodes.length) return [];

        // Build parent-child map
        const childrenMap = new Map();
        const parentMap = new Map();

        edges.forEach(e => {
          if (!childrenMap.has(e.source)) childrenMap.set(e.source, []);
          childrenMap.get(e.source).push(e.target);
          parentMap.set(e.target, e.source);
        });

        // Find root nodes (no parent)
        const roots = nodes.filter(n => !parentMap.has(n.id));

        // BFS to assign positions
        const positions = new Map();
        const queue = roots.map((n, i) => ({ id: n.id, depth: 0, index: i }));
        const depthCounts = new Map();

        while (queue.length > 0) {
          const { id, depth, index } = queue.shift();

          if (!depthCounts.has(depth)) depthCounts.set(depth, 0);
          const xIndex = depthCounts.get(depth);
          depthCounts.set(depth, xIndex + 1);

          positions.set(id, { x: xIndex * 220, y: depth * 120 });

          const children = childrenMap.get(id) || [];
          children.forEach((childId, i) => {
            queue.push({ id: childId, depth: depth + 1, index: i });
          });
        }

        // Apply positions and styling
        return nodes.map(n => ({
          ...n,
          position: positions.get(n.id) || { x: 0, y: 0 },
          type: 'custom',
          className: 'react-flow__node-custom ' + (n.data.status || 'running'),
        }));
      }

      const onNodeClick = useCallback((event, node) => {
        setSelectedNode(node);
      }, []);

      // Format timestamp for display
      function formatTime(iso) {
        if (!iso) return '-';
        const d = new Date(iso);
        return d.toLocaleTimeString();
      }

      return React.createElement('div', { className: 'flex h-screen' },
        // Left sidebar - trace list
        React.createElement('div', { className: 'w-80 bg-gray-800 border-r border-gray-700 overflow-auto' },
          React.createElement('div', { className: 'p-4 border-b border-gray-700' },
            React.createElement('h1', { className: 'text-xl font-bold' }, '⚡ Execution Traces'),
            React.createElement('p', { className: 'text-sm text-gray-400 mt-1' }, 'Lead Reactivation System')
          ),
          React.createElement('div', { className: 'p-2' },
            loading
              ? React.createElement('div', { className: 'text-center py-8 text-gray-400' }, 'Loading...')
              : traces.length === 0
                ? React.createElement('div', { className: 'text-center py-8 text-gray-400' }, 'No traces yet')
                : traces.map(trace =>
                    React.createElement('div', {
                      key: trace.trace_id,
                      className: 'p-3 mb-2 rounded-lg cursor-pointer transition-colors ' +
                        (selectedTrace === trace.trace_id ? 'bg-blue-900 border border-blue-600' : 'bg-gray-700 hover:bg-gray-600'),
                      onClick: () => setSelectedTrace(trace.trace_id)
                    },
                      React.createElement('div', { className: 'flex items-center justify-between' },
                        React.createElement('span', { className: 'font-medium' }, trace.trigger_type || 'scheduler_run'),
                        React.createElement('span', {
                          className: 'px-2 py-0.5 rounded text-xs ' + (statusColors[trace.status] || 'bg-gray-600')
                        }, trace.status)
                      ),
                      React.createElement('div', { className: 'text-xs text-gray-400 mt-1' },
                        formatTime(trace.started_at),
                        trace.duration_ms && ' • ' + trace.duration_ms + 'ms'
                      ),
                      React.createElement('div', { className: 'text-xs text-gray-400' },
                        (trace.leads_processed || 0) + ' leads, ' + (trace.calls_initiated || 0) + ' calls'
                      ),
                      trace.error_count > 0 && React.createElement('div', { className: 'text-xs text-red-400' },
                        trace.error_count + ' error(s)'
                      )
                    )
                  )
          )
        ),

        // Main content - flow diagram
        React.createElement('div', { className: 'flex-1 relative' },
          nodes.length > 0
            ? React.createElement(ReactFlow, {
                nodes: nodes,
                edges: edges,
                onNodesChange: onNodesChange,
                onEdgesChange: onEdgesChange,
                onNodeClick: onNodeClick,
                nodeTypes: nodeTypes,
                fitView: true,
                fitViewOptions: { padding: 0.2 },
              },
                React.createElement(Background, { color: '#374151', gap: 20 }),
                React.createElement(Controls, { className: 'bg-gray-800 border-gray-700' }),
                React.createElement(MiniMap, {
                  className: 'bg-gray-800',
                  nodeColor: n => n.data?.status === 'success' ? '#10b981' : n.data?.status === 'error' ? '#ef4444' : '#3b82f6'
                })
              )
            : React.createElement('div', { className: 'flex items-center justify-center h-full text-gray-400' },
                'Select a trace to view execution flow'
              )
        ),

        // Right sidebar - node details
        selectedNode && React.createElement('div', { className: 'w-96 bg-gray-800 border-l border-gray-700 overflow-auto' },
          React.createElement('div', { className: 'p-4 border-b border-gray-700 flex justify-between items-center' },
            React.createElement('h2', { className: 'font-bold' }, 'Node Details'),
            React.createElement('button', {
              className: 'text-gray-400 hover:text-white',
              onClick: () => setSelectedNode(null)
            }, '✕')
          ),
          React.createElement('div', { className: 'p-4 space-y-4' },
            React.createElement('div', null,
              React.createElement('div', { className: 'text-xs text-gray-400 uppercase' }, 'Name'),
              React.createElement('div', { className: 'font-medium' },
                (nodeIcons[selectedNode.data.nodeType] || '') + ' ' + selectedNode.data.label
              )
            ),
            React.createElement('div', null,
              React.createElement('div', { className: 'text-xs text-gray-400 uppercase' }, 'Status'),
              React.createElement('span', {
                className: 'px-2 py-1 rounded text-sm ' + (statusColors[selectedNode.data.status] || 'bg-gray-600')
              }, selectedNode.data.status)
            ),
            React.createElement('div', null,
              React.createElement('div', { className: 'text-xs text-gray-400 uppercase' }, 'Duration'),
              React.createElement('div', null, selectedNode.data.duration != null ? selectedNode.data.duration + 'ms' : '-')
            ),
            React.createElement('div', null,
              React.createElement('div', { className: 'text-xs text-gray-400 uppercase' }, 'Time'),
              React.createElement('div', { className: 'text-sm' },
                formatTime(selectedNode.data.startedAt) + ' → ' + formatTime(selectedNode.data.endedAt)
              )
            ),
            selectedNode.data.error && React.createElement('div', null,
              React.createElement('div', { className: 'text-xs text-red-400 uppercase' }, 'Error'),
              React.createElement('div', { className: 'text-red-300 text-sm bg-red-900/30 p-2 rounded' },
                selectedNode.data.error
              )
            ),
            selectedNode.data.input && React.createElement('div', null,
              React.createElement('div', { className: 'text-xs text-gray-400 uppercase' }, 'Input'),
              React.createElement('pre', { className: 'text-xs bg-gray-900 p-2 rounded overflow-auto max-h-40' },
                JSON.stringify(selectedNode.data.input, null, 2)
