48→  // Split into statements (naive split on semicolons, but works for our SQL)
49→  const statements = migrationSql
50→    .split(/;\s*$/m)
51→    .map(s => s.trim())
52→    .filter(s => s.length > 0 && !s.startsWith('--'));
53→
54→  for (const statement of statements) {
55→    try {
56→      // Skip pure comments
57→      if (statement.split('\n').every(line => line.trim().startsWith('--') || line.trim() === '')) {
58→        continue;
59→      }
60→      await sql.unsafe(statement);
61→      const firstLine = statement.split('\n').find(l => l.trim() && !l.trim().startsWith('--')) || statement.slice(0, 50);
62→      console.log('✓', firstLine.slice(0, 60) + (firstLine.length > 60 ? '...' : ''));
63→    } catch (error: any) {
64→      // Ignore "already exists" errors for CREATE TABLE IF NOT EXISTS
65→      if (error.message?.includes('already exists')) {
