 29→/**
 30→ * Extract JWT from request headers or cookies
 31→ */
 32→export function extractJWT(c: Context<AppEnv>): string | null {
 33→  const jwtHeader = c.req.header('CF-Access-JWT-Assertion');
 34→  const jwtCookie = c.req.raw.headers.get('Cookie')
 35→    ?.split(';')
 36→    .find(cookie => cookie.trim().startsWith('CF_Authorization='))
 37→    ?.split('=')[1];
