 42→/**
 43→ * Create a Cloudflare Access authentication middleware
 44→ * 
 45→ * @param options - Middleware options
 46→ * @returns Hono middleware function
 47→ */
 48→export function createAccessMiddleware(options: AccessMiddlewareOptions) {
 49→  const { type, redirectOnMissing = false } = options;
 50→
 51→  return async (c: Context<AppEnv>, next: Next) => {
 52→    // Skip auth in dev mode or E2E test mode
 53→    if (isDevMode(c.env) || isE2ETestMode(c.env)) {
 54→      c.set('accessUser', { email: 'dev@localhost', name: 'Dev User' });
 55→      return next();
 56→    }
 57→
 58→    const teamDomain = c.env.CF_ACCESS_TEAM_DOMAIN;
 59→    const expectedAud = c.env.CF_ACCESS_AUD;
 60→
 61→    // Check if CF Access is configured
 62→    if (!teamDomain || !expectedAud) {
 63→      if (type === 'json') {
 64→        return c.json({
 65→          error: 'Cloudflare Access not configured',
 66→          hint: 'Set CF_ACCESS_TEAM_DOMAIN and CF_ACCESS_AUD environment variables',
 67→        }, 500);
 68→      } else {
 69→        return c.html(`
 70→          <html>
 71→            <body>
 72→              <h1>Admin UI Not Configured</h1>
 73→              <p>Set CF_ACCESS_TEAM_DOMAIN and CF_ACCESS_AUD environment variables.</p>
 74→            </body>
 75→          </html>
 76→        `, 500);
 77→      }
 78→    }
 79→
 80→    // Get JWT
 81→    const jwt = extractJWT(c);
 82→
 83→    if (!jwt) {
 84→      if (type === 'html' && redirectOnMissing) {
 85→        return c.redirect(`https://${teamDomain}`, 302);
 86→      }
 87→      
 88→      if (type === 'json') {
 89→        return c.json({
 90→          error: 'Unauthorized',
 91→          hint: 'Missing Cloudflare Access JWT. Ensure this route is protected by Cloudflare Access.',
 92→        }, 401);
 93→      } else {
 94→        return c.html(`
 95→          <html>
 96→            <body>
 97→              <h1>Unauthorized</h1>
 98→              <p>Missing Cloudflare Access token.</p>
 99→              <a href="https://${teamDomain}">Login</a>
100→            </body>
101→          </html>
102→        `, 401);
103→      }
104→    }
105→
106→    // Verify JWT
107→    try {
108→      const payload = await verifyAccessJWT(jwt, teamDomain, expectedAud);
109→      c.set('accessUser', { email: payload.email, name: payload.name });
110→      await next();
111→    } catch (err) {
112→      console.error('Access JWT verification failed:', err);
113→      
114→      if (type === 'json') {
115→        return c.json({
116→          error: 'Unauthorized',
117→          details: err instanceof Error ? err.message : 'JWT verification failed',
118→        }, 401);
119→      } else {
120→        return c.html(`
121→          <html>
122→            <body>
123→              <h1>Unauthorized</h1>
124→              <p>Your Cloudflare Access session is invalid or expired.</p>
125→              <a href="https://${teamDomain}">Login again</a>
126→            </body>
127→          </html>
128→        `, 401);
129→      }
130→    }
131→  };
132→}
