 26→/**
 27→ * Call Claude via CLI (uses subscription auth, no API key needed)
 28→ */
 29→async function callClaude(
 30→  messages: Array<{ role: "user" | "assistant"; content: string }>,
 31→  onChunk?: (text: string) => void
 32→): Promise<string> {
 33→  const contextLines: string[] = [];
 34→  const recent = messages.slice(-10);
 35→  for (const msg of recent.slice(0, -1)) {
 36→    const prefix = msg.role === "user" ? "User" : "Poseidon";
 37→    contextLines.push(`${prefix}: ${msg.content}`);
 38→  }
 39→  const lastMsg = recent[recent.length - 1];
 40→  let userPrompt = lastMsg.content;
 41→  if (contextLines.length > 0) {
 42→    userPrompt = `Previous conversation:\n${contextLines.join("\n")}\n\nUser: ${lastMsg.content}`;
 43→  }
 44→
 45→  return new Promise((resolve, reject) => {
 46→    const env = { ...process.env };
 47→    delete env.ANTHROPIC_API_KEY;
 48→
 49→    const args = [
 50→      "--print",
 51→      "--model",
 52→      "sonnet",
 53→      "--tools",
 54→      "",
 55→      "--output-format",
 56→      "text",
 57→      "--setting-sources",
 58→      "",
 59→      "--system-prompt",
 60→      SYSTEM_PROMPT,
 61→      userPrompt,
 62→    ];
 63→
 64→    let stdout = "";
 65→    let stderr = "";
 66→
 67→    const proc = spawn("claude", args, {
 68→      env,
 69→      stdio: ["ignore", "pipe", "pipe"],
 70→    });
 71→
 72→    proc.stdout.on("data", (data) => {
 73→      const text = data.toString();
 74→      stdout += text;
 75→      if (onChunk) onChunk(text);
 76→    });
 77→
 78→    proc.stderr.on("data", (data) => {
 79→      stderr += data.toString();
 80→    });
 81→
 82→    const timeoutId = setTimeout(() => {
 83→      proc.kill("SIGTERM");
 84→      reject(new Error("Response timeout after 30s"));
 85→    }, 30000);
 86→
 87→    proc.on("close", (code) => {
 88→      clearTimeout(timeoutId);
 89→      if (code !== 0) {
 90→        reject(new Error(stderr || `claude exited with code ${code}`));
 91→      } else {
 92→        resolve(stdout.trim());
 93→      }
 94→    });
 95→
 96→    proc.on("error", (err) => {
 97→      clearTimeout(timeoutId);
 98→      reject(err);
 99→    });
100→  });
101→}
