 1→#!/usr/bin/env bun
 2→/**
 3→ * Database Migration Script
 4→ *
 5→ * Run the execution_traces migration against Supabase.
 6→ * Requires DATABASE_URL environment variable (Supabase connection string).
 7→ *
 8→ * Usage:
 9→ *   DATABASE_URL="postgresql://postgres:PASSWORD@db.PROJECT.supabase.co:5432/postgres" bun migrate.ts
10→ *
11→ * Get your connection string from:
12→ *   Supabase Dashboard → Project Settings → Database → Connection string (URI)
13→ */
14→
15→import postgres from 'postgres';
16→import { readFileSync } from 'fs';
17→
18→const DATABASE_URL = process.env.DATABASE_URL;
19→
20→if (!DATABASE_URL) {
21→  console.log(`
22→╔═══════════════════════════════════════════════════════════════════╗
23→║  Missing DATABASE_URL                                             ║
24→╠═══════════════════════════════════════════════════════════════════╣
25→║  Get your connection string from Supabase:                        ║
26→║                                                                   ║
27→║  1. Go to: https://supabase.com/dashboard                         ║
28→║  2. Select your project                                           ║
29→║  3. Settings → Database → Connection string → URI                 ║
30→║  4. Run:                                                          ║
31→║                                                                   ║
32→║     DATABASE_URL="your-connection-string" bun migrate.ts          ║
33→║                                                                   ║
34→║  Or run the SQL manually in the Supabase SQL Editor:              ║
35→║     cat ../lead-reactivation-github/sql/002_execution_traces.sql  ║
36→╚═══════════════════════════════════════════════════════════════════╝
37→`);
38→  process.exit(1);
39→}
40→
41→const sql = postgres(DATABASE_URL);
42→
43→async function migrate() {
44→  console.log('Running execution_traces migration...');
45→
46→  const migrationSql = readFileSync('/root/lead-reactivation-github/sql/002_execution_traces.sql', 'utf-8');
47→
48→  // Split into statements (naive split on semicolons, but works for our SQL)
49→  const statements = migrationSql
50→    .split(/;\s*$/m)
51→    .map(s => s.trim())
52→    .filter(s => s.length > 0 && !s.startsWith('--'));
53→
54→  for (const statement of statements) {
55→    try {
56→      // Skip pure comments
57→      if (statement.split('\n').every(line => line.trim().startsWith('--') || line.trim() === '')) {
58→        continue;
59→      }
60→      await sql.unsafe(statement);
61→      const firstLine = statement.split('\n').find(l => l.trim() && !l.trim().startsWith('--')) || statement.slice(0, 50);
62→      console.log('✓', firstLine.slice(0, 60) + (firstLine.length > 60 ? '...' : ''));
63→    } catch (error: any) {
64→      // Ignore "already exists" errors for CREATE TABLE IF NOT EXISTS
65→      if (error.message?.includes('already exists')) {
66→        console.log('⊘ (exists)', statement.slice(0, 50) + '...');
67→      } else {
68→        console.error('✗ Error:', error.message);
69→        console.error('  Statement:', statement.slice(0, 100) + '...');
70→      }
71→    }
72→  }
73→
74→  await sql.end();
75→  console.log('\n✓ Migration complete!');
76→}
77→
78→migrate().catch(console.error);
