  1→/**
  2→ * Lead Reactivation Worker
  3→ *
  4→ * Cloudflare Worker that replaces n8n workflows for lead reactivation calling.
  5→ *
  6→ * Endpoints:
  7→ *   GET  /api/health       - Health check
  8→ *   POST /api/import       - Import leads (requires API key)
  9→ *   POST /webhook/retell   - Retell webhook callback
 10→ *
 11→ * Cron: Every 15 minutes - Schedule calls
 12→ */
 13→
 14→import type { Env } from './lib/types';
 15→import { handleHealthCheck } from './handlers/health';
 16→import { handleLeadImport } from './handlers/import';
 17→import { handleRetellWebhook } from './handlers/webhook';
 18→import { handleSkyvernCallback } from './handlers/skyvern-callback';
 19→import { handleScheduledCalls, logSchedulerResult } from './handlers/scheduler';
 20→import { handleListCentres } from './handlers/centres';
 21→import { handleCheckDuplicateLeads } from './handlers/test-leads';
 22→import { handleResetLeadToPending } from './handlers/test-reset-lead';
 23→import { handleCheckCallAttempts } from './handlers/test-call-attempts';
 24→import { handleGetLeadDetails } from './handlers/test-lead-details';
 25→import { handleDashboard, handleDashboardAPI } from './handlers/dashboard';
 26→
 27→export default {
 28→  /**
 29→   * Handle HTTP requests
 30→   */
 31→  async fetch(request: Request, env: Env): Promise<Response> {
 32→    const url = new URL(request.url);
 33→    const path = url.pathname;
 34→    const method = request.method;
 35→
 36→    // CORS preflight
 37→    if (method === 'OPTIONS') {
 38→      return new Response(null, {
 39→        headers: {
 40→          'Access-Control-Allow-Origin': '*',
 41→          'Access-Control-Allow-Methods': 'GET, POST, OPTIONS',
 42→          'Access-Control-Allow-Headers': 'Content-Type, Authorization',
 43→        },
 44→      });
 45→    }
 46→
 47→    // Route requests
 48→    try {
 49→      // Health check
 50→      if (path === '/api/health' && method === 'GET') {
 51→        return await handleHealthCheck(env);
 52→      }
 53→
 54→      // List centres
 55→      if (path === '/api/centres' && method === 'GET') {
 56→        return await handleListCentres(env);
 57→      }
 58→
 59→      // Lead import
 60→      if (path === '/api/import' && method === 'POST') {
 61→        return await handleLeadImport(request, env);
 62→      }
 63→
 64→      // Retell webhook
 65→      if (path === '/webhook/retell' && method === 'POST') {
 66→        return await handleRetellWebhook(request, env);
 67→      }
 68→
 69→      // Skyvern callback webhook
 70→      if (path === '/webhook/skyvern' && method === 'POST') {
 71→        return await handleSkyvernCallback(request, env);
 72→      }
 73→
 74→      // Check for duplicate leads by phone
 75→      if (path.startsWith('/api/check-duplicates/') && method === 'GET') {
 76→        const phone = decodeURIComponent(path.split('/api/check-duplicates/')[1]);
 77→        return await handleCheckDuplicateLeads(env, phone);
 78→      }
 79→
 80→      // Reset lead to pending (test endpoint)
 81→      if (path.startsWith('/api/reset-lead/') && method === 'POST') {
 82→        const leadId = path.split('/api/reset-lead/')[1];
 83→        return await handleResetLeadToPending(env, leadId);
 84→      }
 85→
 86→      // Check call attempts by phone
 87→      if (path.startsWith('/api/call-attempts/') && method === 'GET') {
 88→        const phone = decodeURIComponent(path.split('/api/call-attempts/')[1]);
 89→        return await handleCheckCallAttempts(env, phone);
 90→      }
 91→
 92→      // Get full lead details
 93→      if (path.startsWith('/api/lead/') && method === 'GET') {
 94→        const leadId = path.split('/api/lead/')[1];
 95→        return await handleGetLeadDetails(env, leadId);
 96→      }
 97→
 98→      // Dashboard - Visual Workload Tracer
 99→      if (path === '/dashboard' && method === 'GET') {
100→        return await handleDashboard(request, env);
101→      }
102→
103→      // Dashboard API
104→      if (path === '/api/dashboard' && method === 'GET') {
105→        return await handleDashboardAPI(request, env);
106→      }
107→
108→      // Manual test trigger (GET for easy browser access)
109→      if (path === '/api/test-call' && (method === 'GET' || method === 'POST')) {
110→        console.log('Manual test call triggered');
111→        const result = await handleScheduledCalls(env);
112→        logSchedulerResult(result);
113→        return new Response(JSON.stringify(result, null, 2), {
114→          headers: { 'Content-Type': 'application/json' },
115→        });
116→      }
117→
118→      // 404 for unknown routes
119→      return new Response(
120→        JSON.stringify({
121→          error: 'Not found',
122→          path,
123→          availableEndpoints: [
124→            'GET /api/health',
125→            'GET /api/centres',
126→            'GET /dashboard',
127→            'POST /api/import',
128→            'POST /webhook/retell',
