 42→/**
 43→ * Creates a phone call via Retell API
 44→ * @param env - Worker environment
 45→ * @param lead - Claimed lead data
 46→ * @param callAttemptId - Call attempt record ID
 47→ * @param formattedSlots - Formatted availability slots string
 48→ * @returns Retell call response with call_id
 49→ */
 50→export async function createPhoneCall(
 51→  env: Env,
 52→  lead: ClaimedLead,
 53→  callAttemptId: string,
 54→  formattedSlots: string
 55→): Promise<RetellCallResponse> {
 56→  // Test mode: override destination phone number
 57→  const isTestMode = env.TEST_MODE === 'true' && env.TEST_PHONE;
 58→  const toNumber = isTestMode ? env.TEST_PHONE! : lead.phone;
 59→
 60→  if (isTestMode) {
 61→    console.warn(`[TEST MODE] Redirecting call for lead ${lead.lead_id} (${lead.first_name} ${lead.last_name}) from ${lead.phone} → ${env.TEST_PHONE}`);
 62→  }
 63→
 64→  // Select agent based on campaign type
 65→  const agentId = lead.campaign_type === 'inbound'
 66→    ? env.RETELL_AGENT_ID_INBOUND
 67→    : env.RETELL_AGENT_ID;
 68→
 69→  // Get latest agent version to use unpublished changes
 70→  const agentVersion = await getLatestAgentVersion(env, agentId);
 71→
 72→  console.log(`Using agent ${agentId} for campaign_type=${lead.campaign_type}`);
 73→
 74→  const requestBody: RetellCallRequest = {
 75→    from_number: lead.twilio_number,
 76→    to_number: toNumber,
 77→    agent_id: agentId,
 78→    override_agent_version: agentVersion, // Use latest version even if unpublished
 79→    metadata: {
 80→      lead_id: lead.lead_id,
 81→      centre_id: lead.centre_id,
 82→      attempt_number: lead.attempt_count + 1,
 83→      call_attempt_id: callAttemptId,
 84→      campaign_type: lead.campaign_type,
 85→    },
 86→    retell_llm_dynamic_variables: {
 87→      FIRST_NAME: lead.first_name,
 88→      LAST_NAME: lead.last_name,
 89→      LOCATION_NAME: lead.location_name,
 90→      TIMEZONE: lead.timezone_display,
 91→      PROGRAM_INTEREST: lead.program_interest || 'CREATE',
 92→      PREVIOUS_NOTES: lead.previous_notes || 'Previous inquiry about programs',
 93→      SLOTS: formattedSlots,
 94→      EMAIL: lead.email || '',
 95→      knowledge_base: lead.knowledge_base || '',
 96→    },
 97→  };
 98→
 99→  const response = await fetch(`${RETELL_API_BASE}/create-phone-call`, {
100→    method: 'POST',
101→    headers: {
102→      'Content-Type': 'application/json',
103→      Authorization: `Bearer ${env.RETELL_API_KEY}`,
104→    },
105→    body: JSON.stringify(requestBody),
106→  });
107→
108→  if (!response.ok) {
109→    const errorText = await response.text();
110→    console.error('Retell API error:', response.status, errorText);
111→    throw new Error(`Retell API error: ${response.status} - ${errorText}`);
112→  }
113→
114→  const data = (await response.json()) as RetellCallResponse;
115→  return data;
116→}
