374→/**
375→ * Imports leads in bulk
376→ * @param env - Worker environment
377→ * @param leads - Array of leads to import
378→ * @returns Import result with counts
379→ */
380→export async function importLeads(
381→  env: Env,
382→  leads: LeadImport[],
383→  batchId?: string
384→): Promise<{ inserted: number; skipped: number; errors: string[] }> {
385→  const supabase = getSupabaseClient(env);
386→  const errors: string[] = [];
387→  let inserted = 0;
388→  let skipped = 0;
389→
390→  const effectiveBatchId = batchId || `batch_${new Date().toISOString().slice(0, 10).replace(/-/g, '_')}`;
391→
392→  for (const lead of leads) {
393→    const normalized = normalizePhone(lead.phone);
394→    if (!normalized) {
395→      errors.push(`Invalid phone: ${lead.phone}`);
396→      skipped++;
397→      continue;
398→    }
399→
400→    // Check for duplicates
401→    const recentlyCalled = await wasRecentlyCalled(env, normalized, 30);
402→    if (recentlyCalled) {
403→      skipped++;
404→      continue;
405→    }
406→
407→    // Determine campaign type and retry scheduling
408→    const campaignType = lead.campaign_type || 'reactivation';
409→    const attemptCount = lead.attempt_count || 0;
410→    const lastOutcome = lead.last_outcome || null;
411→
412→    // For inbound leads with prior attempts, calculate next_call_after using retry cadence
413→    let nextCallAfter: string | null = null;
414→    let status: 'pending' | 'exhausted' = 'pending';
415→
416→    if (attemptCount > 0) {
417→      const retry = calculateRetry(attemptCount - 1, [], null, campaignType as CampaignType);
418→      nextCallAfter = retry.nextCallAfter;
419→      status = retry.newStatus;
420→    }
421→
422→    // Insert the lead
423→    const { error } = await supabase.from('leads').insert({
424→      centre_id: lead.centre_id,
425→      first_name: lead.first_name,
426→      last_name: lead.last_name,
427→      phone: normalized,
428→      email: lead.email || null,
429→      program_interest: lead.program_interest || null,
430→      previous_notes: lead.previous_notes || null,
431→      campaign_type: campaignType,
432→      batch_id: effectiveBatchId,
433→      source: 'api',
434→      status,
435→      attempt_count: attemptCount,
436→      last_outcome: lastOutcome,
437→      next_call_after: nextCallAfter,
438→    });
439→
440→    if (error) {
441→      errors.push(`Failed to insert ${lead.phone}: ${error.message}`);
442→      skipped++;
443→    } else {
444→      inserted++;
445→    }
446→  }
447→
448→  return { inserted, skipped, errors };
449→}
