  1→/**
  2→ * Retell webhook handler
  3→ * Processes call completion callbacks
  4→ *
  5→ * Now includes execution tracing for observability dashboard
  6→ */
  7→
  8→import type { Env, RetellWebhookPayload } from '../lib/types';
  9→import { determineOutcome, isFinalOutcome, isRetryOutcome } from '../lib/outcomes';
 10→import { calculateRetry, type CampaignType } from '../lib/retry';
 11→import {
 12→  releaseLead,
 13→  updateCallAttemptFromWebhook,
 14→  updateCallAnalytics,
 15→  markLeadCompleted,
 16→  updateLeadForRetry,
 17→  getLeadById,
 18→  getCentreById,
 19→  setSkyvernTaskId,
 20→  updateBookingStatus,
 21→} from '../services/supabase';
 22→import { triggerBooking, validateTourDate } from '../services/skyvern';
 23→import { Tracer } from '../services/tracing';
 24→
 25→/**
 26→ * Handles Retell webhook callbacks
 27→ * POST /webhook/retell
 28→ */
 29→export async function handleRetellWebhook(request: Request, env: Env): Promise<Response> {
 30→  let payload: RetellWebhookPayload;
 31→
 32→  try {
 33→    payload = await request.json();
 34→  } catch {
 35→    return errorResponse(400, 'Invalid JSON body');
 36→  }
 37→
 38→  // Retell sends { event: "call_ended", call: {...} } - extract the call object
 39→  const callData = payload.call || payload;
 40→
 41→  // Extract data from payload
 42→  const callId = callData.call_id;
 43→  const metadata = callData.metadata || {};
 44→  const callAnalysis = callData.call_analysis || {};
 45→
 46→  const leadId = metadata.lead_id;
 47→  const centreId = metadata.centre_id;
 48→  const attemptNumber = parseInt(String(metadata.attempt_number)) || 1;
 49→  const campaignType = metadata.campaign_type || 'reactivation';
 50→
 51→  // Validate required fields
 52→  if (!leadId) {
 53→    console.warn('Webhook received without lead_id:', callId);
 54→    return errorResponse(400, 'Missing lead_id in metadata');
 55→  }
 56→
 57→  // Determine outcome - check custom_analysis_data first (where Retell puts custom fields)
 58→  const customData = callAnalysis.custom_analysis_data || {};
 59→  const outcome = determineOutcome(
 60→    customData.outcome || callAnalysis.outcome || callAnalysis.call_outcome,
 61→    callData.disconnection_reason
 62→  );
 63→
 64→  const durationMs = callData.duration_ms || callData.call_length_ms || 0;
 65→  const durationSeconds = Math.round(durationMs / 1000);
 66→  const emailPermission = customData.email_permission || callAnalysis.email_permission || false;
 67→  const appointmentBooked = customData.appointment_booked || callAnalysis.appointment_booked || false;
 68→  const callSummary = customData.detailed_call_summary || callAnalysis.detailed_call_summary || callAnalysis.call_summary || '';
 69→
 70→  console.log(`Processing webhook for lead ${leadId}: outcome=${outcome}, duration=${durationSeconds}s`);
 71→
 72→  // Start execution trace for this webhook
 73→  const tracer = await Tracer.create(env, 'retell_webhook', 'webhook', {
 74→    call_id: callId,
 75→    lead_id: leadId,
 76→    outcome,
 77→    duration_seconds: durationSeconds,
 78→    appointment_booked: appointmentBooked,
 79→  });
 80→
 81→  try {
 82→    // 1. Release the lead (decrement active_calls counter)
 83→    await tracer.wrap('release_lead', 'database', () => releaseLead(env, leadId), {
 84→      leadId,
 85→      centreId,
 86→    });
 87→
 88→    // 2. Update call_attempts record
 89→    if (callId) {
 90→      await tracer.wrap(
 91→        'update_call_attempt',
 92→        'database',
 93→        () =>
 94→          updateCallAttemptFromWebhook(env, callId, {
 95→            outcome,
 96→            call_summary: callSummary,
 97→            email_permission: emailPermission,
 98→            appointment_booked: appointmentBooked,
 99→            duration_seconds: durationSeconds,
100→            webhook_payload: payload,
101→          }),
102→        { leadId, inputData: { outcome, duration_seconds: durationSeconds } }
103→      );
104→    }
105→
106→    // 3. Update analytics
107→    if (centreId) {
108→      await tracer.wrap(
109→        'update_analytics',
110→        'database',
111→        () => updateCallAnalytics(env, centreId, campaignType, outcome, durationSeconds),
112→        { centreId, inputData: { outcome, campaign_type: campaignType } }
113→      );
114→    }
115→
116→    // 4. Route by outcome
117→    if (isFinalOutcome(outcome)) {
118→      // Mark lead as completed
119→      await tracer.wrap(
120→        'mark_lead_completed',
121→        'database',
122→        () =>
123→          markLeadCompleted(env, leadId, {
124→            last_outcome: outcome,
125→            appointment_booked: appointmentBooked,
126→            email_permission: emailPermission,
127→            detailed_call_summary: callSummary,
128→          }),
129→        { leadId, inputData: { outcome, appointment_booked: appointmentBooked } }
130→      );
131→
132→      // Trigger Skyvern if booked
133→      if (outcome === 'booked' && appointmentBooked && centreId) {
134→        const skyvernSpan = await tracer.span('trigger_skyvern_booking', 'api', {
135→          leadId,
136→          centreId,
137→          inputData: { outcome: 'booked' },
138→        });
139→
140→        try {
141→          const customData = callAnalysis.custom_analysis_data || {};
142→          const tourDate = customData['Tour Date'] || customData.tour_date || '';
143→          const tourTime = customData['Tour Time'] || customData.tour_time || '';
144→          const childName = customData['Child First Name'] || customData.child_name || '';
145→          const childAge = customData["Child's Age"] || customData.child_age || '';
146→
147→          let childBirthYear: number | undefined;
148→          if (childAge && !isNaN(parseInt(childAge))) {
149→            childBirthYear = new Date().getFullYear() - parseInt(childAge);
150→          }
151→
152→          const [leadData, centreData] = await Promise.all([
153→            getLeadById(env, leadId),
154→            getCentreById(env, centreId),
155→          ]);
156→
157→          if (leadData && centreData?.availability_api_url) {
158→            const selectedSlot = callAnalysis.selected_slot || extractSlotFromSummary(callSummary);
159→
160→            const bookingResult = await triggerBooking(env, {
161→              action: 'book_tour',
162→              lead_id: leadId,
163→              centre_id: centreId,
164→              first_name: leadData.first_name,
165→              last_name: leadData.last_name,
166→              phone: leadData.phone,
167→              email: leadData.email || '',
168→              selected_slot: selectedSlot,
169→              call_summary: callSummary,
170→              tour_date: tourDate,
171→              tour_time: tourTime,
172→              child_name: childName || leadData.first_name,
173→              child_birth_year: childBirthYear,
174→            });
175→
176→            if (bookingResult.success && bookingResult.task_id) {
177→              await setSkyvernTaskId(env, leadId, bookingResult.task_id, tourDate, tourTime);
178→              console.log(`Skyvern task ${bookingResult.task_id} tracked for lead ${leadId}`);
179→              await tracer.end(skyvernSpan.spanId, 'success', {
180→                outputData: { task_id: bookingResult.task_id, tour_date: tourDate, tour_time: tourTime },
181→              });
182→            } else if (!bookingResult.success) {
183→              await updateBookingStatus(env, leadId, {
184→                booking_status: 'failed',
185→                booking_failure_reason: bookingResult.error || 'Unknown error',
186→              });
187→              console.warn(`Skyvern booking failed for lead ${leadId}: ${bookingResult.error}`);
188→              await tracer.end(skyvernSpan.spanId, 'error', {
189→                errorMessage: bookingResult.error || 'Unknown error',
190→              });
191→            }
192→          } else {
193→            console.warn('Missing lead or centre data for Skyvern booking:', { leadId, centreId });
194→            await updateBookingStatus(env, leadId, {
195→              booking_status: 'failed',
196→              booking_failure_reason: 'Missing lead or centre data',
197→            });
198→            await tracer.end(skyvernSpan.spanId, 'error', {
199→              errorMessage: 'Missing lead or centre data',
200→            });
201→          }
202→        } catch (bookingError) {
203→          console.error(`Skyvern booking error for lead ${leadId}:`, bookingError);
204→          await tracer.end(skyvernSpan.spanId, 'error', {
205→            errorMessage: String(bookingError),
206→          });
207→        }
208→      }
209→    } else if (isRetryOutcome(outcome)) {
210→      // Calculate retry timing
211→      const retry = calculateRetry(attemptNumber - 1, [], null, campaignType as CampaignType);
212→
213→      await tracer.wrap(
214→        'schedule_retry',
215→        'database',
216→        () =>
217→          updateLeadForRetry(env, leadId, {
218→            status: retry.newStatus,
219→            attempt_count: retry.newAttemptCount,
220→            call_windows_tried: retry.callWindowsTried,
221→            next_call_after: retry.nextCallAfter,
222→            last_outcome: outcome,
223→            detailed_call_summary: callSummary,
224→          }),
225→        {
226→          leadId,
227→          inputData: {
228→            new_status: retry.newStatus,
229→            new_attempt_count: retry.newAttemptCount,
230→            next_call_after: retry.nextCallAfter,
231→          },
232→        }
233→      );
234→    } else {
235→      // Unknown outcome - mark as pending for manual review
236→      await tracer.wrap(
237→        'mark_pending_review',
238→        'database',
239→        () =>
240→          updateLeadForRetry(env, leadId, {
241→            status: 'pending',
242→            attempt_count: attemptNumber,
243→            call_windows_tried: [],
244→            next_call_after: null,
245→            last_outcome: outcome,
246→            detailed_call_summary: callSummary,
247→          }),
248→        { leadId, inputData: { outcome, reason: 'unknown_outcome' } }
249→      );
250→    }
251→
252→    // Finalize trace
253→    await tracer.finalize('success', {
254→      outputData: { outcome, lead_id: leadId },
255→      metadata: { outcome, appointment_booked: appointmentBooked },
256→    });
257→
258→    return new Response(
259→      JSON.stringify({
260→        status: 'ok',
261→        lead_id: leadId,
262→        outcome,
263→        trace_id: tracer.context.traceId,
264→      }),
265→      {
266→        status: 200,
267→        headers: { 'Content-Type': 'application/json' },
268→      }
269→    );
270→  } catch (error) {
271→    console.error('Webhook processing error:', error);
272→
273→    await tracer.finalize('error', {
274→      errorMessage: String(error),
275→    });
276→
277→    return errorResponse(500, `Processing failed: ${error}`);
278→  }
279→}
