281→function errorResponse(status: number, message: string): Response {
282→  return new Response(
283→    JSON.stringify({
284→      status: 'error',
285→      error: message,
286→    }),
287→    {
288→      status,
289→      headers: { 'Content-Type': 'application/json' },
290→    }
291→  );
292→}
