294→/**
295→ * Extracts a selected time slot from the call summary
296→ * Looks for patterns like "Thursday February 5 at 6pm" or "2026-02-05 at 6:00 PM"
297→ */
298→function extractSlotFromSummary(summary: string): string {
299→  if (!summary) return '';
300→
301→  // Look for day + date + time pattern (e.g., "Thursday February 5 at 6pm")
302→  const dayPattern = /(Monday|Tuesday|Wednesday|Thursday|Friday|Saturday|Sunday)\s+\w+\s+\d{1,2}\s+at\s+\d{1,2}(?::\d{2})?\s*(?:am|pm)/i;
303→  const dayMatch = summary.match(dayPattern);
304→  if (dayMatch) return dayMatch[0];
