import React, { useState, useEffect } from 'react';
import DateFilter from './DateFilter';

interface CallItem {
  call_id: string;
  direction: string;
  agent_type: string;
  agent_label: string;
  from_number: string;
  to_number: string;
  duration_seconds: number;
  started_at: string;
  outcome: string;
  sentiment: string;
  summary: string;
  in_voicemail: boolean;
}

const outcomeColors: Record<string, string> = {
  booked: 'bg-green-600',
  interested: 'bg-blue-600',
  callback: 'bg-yellow-600',
  completed: 'bg-gray-600',
  voicemail: 'bg-purple-600',
  not_interested: 'bg-red-600/60',
  unknown: 'bg-gray-700',
};

function formatDuration(seconds: number): string {
  const m = Math.floor(seconds / 60);
  const s = seconds % 60;
  return `${m}:${s.toString().padStart(2, '0')}`;
}

function formatTime(iso: string): string {
  if (!iso) return '-';
  const d = new Date(iso);
  return d.toLocaleDateString('en-US', { month: 'short', day: 'numeric' }) +
    ' ' + d.toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit' });
}

function formatPhone(phone: string): string {
  if (!phone) return '-';
  const clean = phone.replace(/\D/g, '');
  if (clean.length === 11 && clean[0] === '1') {
    return `(${clean.slice(1, 4)}) ${clean.slice(4, 7)}-${clean.slice(7)}`;
  }
  return phone;
}

async function apiFetch(path: string) {
  const token = localStorage.getItem('tf_access_token');
  const res = await fetch(path, {
    headers: { Authorization: `Bearer ${token}` },
  });
  if (res.status === 401) {
    localStorage.clear();
    window.location.href = '/';
    throw new Error('Unauthorized');
  }
  return res.json();
}

export default function CallLog() {
  const [calls, setCalls] = useState<CallItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  useEffect(() => {
    loadCalls();
  }, []);

  async function loadCalls() {
    setLoading(true);
    setError('');
    try {
      const data = await apiFetch('/api/calls?limit=100');
      setCalls(data);
    } catch (e) {
      setError('Failed to load calls');
    } finally {
      setLoading(false);
    }
  }

  if (loading) {
    return (
      <div className="flex items-center justify-center h-64">
        <div className="text-gray-400">Loading calls...</div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="flex items-center justify-center h-64">
        <div className="text-red-400">{error}</div>
      </div>
    );
  }

  return (
    <div>
      <div className="flex items-center justify-between mb-6">
        <h2 className="text-xl font-semibold text-white">Call Log</h2>
        <button
          onClick={loadCalls}
          className="text-sm px-3 py-1.5 rounded-lg text-gray-300 hover:text-white transition-colors"
          style={{ border: '1px solid var(--tf-border)' }}
        >
          Refresh
        </button>
      </div>

      {calls.length === 0 ? (
        <div className="text-center py-16 text-gray-500">No calls yet</div>
      ) : (
        <div className="rounded-xl overflow-hidden" style={{ border: '1px solid var(--tf-border)' }}>
          <table className="w-full text-sm">
            <thead>
              <tr style={{ background: 'var(--tf-navy-light)' }}>
                <th className="text-left px-4 py-3 text-gray-400 font-medium">Date / Time</th>
                <th className="text-left px-4 py-3 text-gray-400 font-medium">Phone</th>
                <th className="text-left px-4 py-3 text-gray-400 font-medium">Type</th>
                <th className="text-left px-4 py-3 text-gray-400 font-medium">Duration</th>
                <th className="text-left px-4 py-3 text-gray-400 font-medium">Outcome</th>
                <th className="text-left px-4 py-3 text-gray-400 font-medium">Summary</th>
              </tr>
            </thead>
            <tbody>
              {calls.map((call) => (
                <tr
                  key={call.call_id}
                  className="hover:bg-white/5 cursor-pointer transition-colors"
                  style={{ borderTop: '1px solid var(--tf-border)' }}
                  onClick={() => { window.location.hash = `/calls/${call.call_id}`; }}
                >
                  <td className="px-4 py-3 text-gray-300 whitespace-nowrap">
                    {formatTime(call.started_at)}
                  </td>
                  <td className="px-4 py-3 text-gray-300 whitespace-nowrap font-mono text-xs">
                    {formatPhone(call.direction === 'inbound' ? call.from_number : call.to_number)}
                  </td>
                  <td className="px-4 py-3">
                    <span className={`text-xs px-2 py-0.5 rounded ${
                      call.direction === 'inbound' ? 'bg-blue-600/20 text-blue-300' : 'bg-gray-600/20 text-gray-300'
                    }`}>
                      {call.direction === 'inbound' ? 'Inbound' : 'Outbound'}
                    </span>
                  </td>
                  <td className="px-4 py-3 text-gray-400 whitespace-nowrap">
                    {formatDuration(call.duration_seconds)}
                  </td>
                  <td className="px-4 py-3">
                    <span className={`text-xs px-2 py-0.5 rounded text-white ${outcomeColors[call.outcome] || outcomeColors.unknown}`}>
                      {call.outcome}
                    </span>
                  </td>
                  <td className="px-4 py-3 text-gray-400 max-w-xs truncate">
                    {call.summary || '-'}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}

export { apiFetch };

