import React, { useState, useEffect } from 'react';
import AudioPlayer from './AudioPlayer';
import TranscriptViewer from './TranscriptViewer';
import { apiFetch } from './CallLog';

interface CallDetailData {
  call_id: string;
  direction: string;
  from_number: string;
  to_number: string;
  duration_seconds: number;
  started_at: string;
  recording_url: string | null;
  transcript: { role: 'agent' | 'user'; content: string }[];
  analysis: Record<string, unknown>;
  disconnection_reason: string;
}

interface Props {
  callId: string;
}

export default function CallDetailView({ callId }: Props) {
  const [call, setCall] = useState<CallDetailData | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  useEffect(() => {
    loadCall();
  }, [callId]);

  async function loadCall() {
    setLoading(true);
    setError('');
    try {
      const data = await apiFetch(`/api/calls/${callId}`);
      setCall(data);
    } catch {
      setError('Failed to load call details');
    } finally {
      setLoading(false);
    }
  }

  if (loading) {
    return (
      <div className="flex items-center justify-center h-64">
        <div className="text-gray-400">Loading call details...</div>
      </div>
    );
  }

  if (error || !call) {
    return (
      <div className="flex items-center justify-center h-64">
        <div className="text-red-400">{error || 'Call not found'}</div>
      </div>
    );
  }

  const analysis = call.analysis as {
    call_summary?: string;
    user_sentiment?: string;
    call_successful?: boolean;
    in_voicemail?: boolean;
    custom_analysis_data?: Record<string, unknown>;
  };

  return (
    <div>
      {/* Back button + header */}
      <div className="flex items-center gap-3 mb-6">
        <a
          href="#/calls"
          className="text-gray-400 hover:text-white transition-colors text-sm"
        >
          &larr; Back to calls
        </a>
        <span className="text-gray-600">|</span>
        <h2 className="text-lg font-semibold text-white">
          Call {call.direction === 'inbound' ? 'from' : 'to'}{' '}
          {call.direction === 'inbound' ? call.from_number : call.to_number}
        </h2>
      </div>

      {/* Info bar */}
      <div
        className="flex flex-wrap gap-6 p-4 rounded-xl mb-6 text-sm"
        style={{ background: 'var(--tf-navy-light)', border: '1px solid var(--tf-border)' }}
      >
        <div>
          <span className="text-gray-500">Date</span>
          <div className="text-gray-200">
            {call.started_at ? new Date(call.started_at).toLocaleString() : '-'}
          </div>
        </div>
        <div>
          <span className="text-gray-500">Duration</span>
          <div className="text-gray-200">
