interface Props {
  callId: string;
}

export default function CallDetailView({ callId }: Props) {
  const [call, setCall] = useState<CallDetailData | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  useEffect(() => {
    loadCall();
  }, [callId]);

  async function loadCall() {
    setLoading(true);
    setError('');
    try {
      const data = await apiFetch(`/api/calls/${callId}`);
      setCall(data);
    } catch {
      setError('Failed to load call details');
