import React from 'react';

interface Utterance {
  role: 'agent' | 'user';
  content: string;
}

interface Props {
  transcript: Utterance[];
}

export default function TranscriptViewer({ transcript }: Props) {
  if (!transcript || transcript.length === 0) {
    return (
      <div
        className="rounded-xl p-8 text-center text-gray-500"
        style={{ background: 'var(--tf-navy-light)', border: '1px solid var(--tf-border)' }}
      >
        No transcript available
      </div>
    );
  }

  return (
    <div
      className="rounded-xl p-4 space-y-3 max-h-[600px] overflow-y-auto"
      style={{ background: 'var(--tf-navy-light)', border: '1px solid var(--tf-border)' }}
    >
      {transcript.map((msg, i) => (
        <div
          key={i}
          className={`flex ${msg.role === 'agent' ? 'justify-end' : 'justify-start'}`}
        >
          <div
            className={`max-w-[80%] px-3 py-2 rounded-xl text-sm leading-relaxed ${
              msg.role === 'agent'
                ? 'rounded-tr-sm text-white'
                : 'rounded-tl-sm text-gray-200'
            }`}
            style={{
              background: msg.role === 'agent' ? 'var(--tf-blue)' : 'rgba(255,255,255,0.08)',
            }}
          >
            <div className="text-[10px] font-medium mb-0.5 opacity-60">
              {msg.role === 'agent' ? 'Agent' : 'Caller'}
            </div>
            {msg.content}
          </div>
        </div>
      ))}
    </div>
  );
}

