/**
 * TourForce Portal — Client-facing dashboard for Voice AI centres
 *
 * Bun.serve() with HTML imports for frontend pages
 * Hono for API routes with auth middleware
 */

import { Hono } from 'hono';
import { cors } from 'hono/cors';
import loginPage from './pages/index.html';
import dashboardPage from './pages/dashboard.html';
import authRoutes from './api/auth';
import callsRoutes from './api/calls';

const PORT = parseInt(process.env.PORT || '4000');

// Build Hono API app
const api = new Hono();
api.use('*', cors());

// Mount API routes
api.route('/api/auth', authRoutes);
api.route('/api/calls', callsRoutes);

// Health check
api.get('/api/health', (c) => c.json({ status: 'ok', timestamp: new Date().toISOString() }));

// Start server
const server = Bun.serve({
  port: PORT,
  routes: {
    '/': loginPage,
    '/dashboard': dashboardPage,
  },
  // Hono handles /api/* and any unmatched routes
  fetch: api.fetch,
  development: {
    hmr: true,
    console: true,
  },
});

