/**
 * TourForce Portal — Migration Runner + Admin User Setup
 *
 * Usage:
 *   bun run migrate.ts --db-url "postgresql://postgres.uajdbjotlqvyursytlph:[PASSWORD]@aws-0-us-east-1.pooler.supabase.com:6543/postgres"
 *
 * Or set DATABASE_URL in .env
 */

import { createClient } from '@supabase/supabase-js';

const SUPABASE_URL = process.env.SUPABASE_URL!;
const SUPABASE_SERVICE_KEY = process.env.SUPABASE_SERVICE_KEY!;

// Parse --db-url flag
const dbUrlFlag = process.argv.find((a) => a.startsWith('--db-url='));
const dbUrlArgIdx = process.argv.indexOf('--db-url');
const DATABASE_URL =
  dbUrlFlag?.split('=').slice(1).join('=') ||
  (dbUrlArgIdx >= 0 ? process.argv[dbUrlArgIdx + 1] : undefined) ||
  process.env.DATABASE_URL;

const serviceClient = createClient(SUPABASE_URL, SUPABASE_SERVICE_KEY);

// Migration files in order
const migrationFiles = [
  'migrations/003_portal_users.sql',
  'migrations/004_centre_agents.sql',
  'migrations/005_rls_policies.sql',
];

async function runMigrations() {
  if (!DATABASE_URL) {
    console.error('ERROR: No database URL provided.');
    console.error('');
    console.error('Get your connection string from:');
    console.error('  https://supabase.com/dashboard/project/uajdbjotlqvyursytlph/settings/database');
    console.error('');
    console.error('Then run:');
    console.error('  bun run migrate.ts --db-url "postgresql://postgres.uajdbjotlqvyursytlph:[YOUR_PASSWORD]@aws-0-us-east-1.pooler.supabase.com:6543/postgres"');
    process.exit(1);
  }

  console.log('Running migrations via psql...\n');

  for (const file of migrationFiles) {
    const sql = await Bun.file(file).text();
    console.log(`  Running ${file}...`);

    const proc = Bun.spawn(['psql', DATABASE_URL, '-c', sql], {
      stdout: 'pipe',
      stderr: 'pipe',
    });

    const stdout = await new Response(proc.stdout).text();
    const stderr = await new Response(proc.stderr).text();
    const exitCode = await proc.exited;

    if (exitCode !== 0) {
      console.error(`  FAILED: ${stderr.trim()}`);
      // Don't exit — some errors are OK (e.g., table already exists)
    } else {
      console.log(`  OK: ${stdout.trim()}`);
    }
  }

  console.log('\nMigrations complete.\n');
}

async function createAdminUser() {
  const email = 'scott.james@codeninjas.com';
  const password = 'TourForce2026!'; // Temporary — Scott should change this

  console.log(`Creating admin user: ${email}...`);

  // Check if user already exists
  const { data: existingUsers } = await serviceClient.auth.admin.listUsers();
  const existing = existingUsers?.users?.find((u) => u.email === email);

  let userId: string;

  if (existing) {
    console.log(`  User already exists (${existing.id}). Skipping auth creation.`);
    userId = existing.id;
  } else {
    const { data, error } = await serviceClient.auth.admin.createUser({
      email,
      password,
      email_confirm: true, // Skip email verification
    });

    if (error) {
      console.error(`  Failed to create auth user: ${error.message}`);
      return;
    }
    userId = data.user.id;
    console.log(`  Auth user created: ${userId}`);
  }

  // Create portal_users row
  console.log('  Creating portal_users row (admin, east-gwillimbury-on-ca)...');
  const { error: puError } = await serviceClient
    .from('portal_users')
    .upsert({
      id: userId,
      centre_id: 'east-gwillimbury-on-ca',
      email,
      full_name: 'Scott James',
      role: 'admin',
    }, { onConflict: 'id' });

  if (puError) {
    console.error(`  Failed to create portal_users row: ${puError.message}`);
    console.error('  (This is expected if migrations haven\'t run yet. Run migrations first.)');
  } else {
    console.log('  Portal user created successfully.');
  }

  console.log(`\n  Login credentials:`);
  console.log(`    Email:    ${email}`);
  console.log(`    Password: ${password}`);
  console.log(`    (Change this password after first login!)\n`);
}

// Run
console.log('╔══════════════════════════════════════════╗');
console.log('║   TourForce Portal — Setup              ║');
console.log('╚══════════════════════════════════════════╝\n');

if (DATABASE_URL) {
  await runMigrations();
}
await createAdminUser();

